import assert from 'node:assert/strict';

// In Z[C3] with basis (1,g,g^2), the augmentation ideal is the zero-sum
// lattice generated by b1=1-g and b2=g-g^2.
const b1=[1,-1,0],b2=[0,1,-1],s=[1,1,1];
const B=[[1,0],[-1,1],[0,-1]];
const G=[[0,0,1],[1,0,0],[0,1,0]];
const mm=(A,B)=>A.map(r=>B[0].map((_,j)=>r.reduce((z,x,k)=>z+x*B[k][j],0)));
const det=M=>M.length===1?M[0][0]:M[0].reduce((z,x,j)=>z+(j%2?-1:1)*x*det(M.slice(1).map(r=>r.filter((_,k)=>k!==j))),0);
const eq=(A,B)=>JSON.stringify(A)===JSON.stringify(B);

const A=[[0,-1],[1,-1]];
assert.ok(eq(mm(G,B),mm(B,A)));
assert.ok(eq(mm(A,mm(A,A)),[[1,0],[0,1]]));

// The trivial invariant line and augmentation ideal span an index-three
// sublattice, so Z[C3] is not their integral direct sum.
const splitMatrix=[
  [s[0],b1[0],b2[0]],
  [s[1],b1[1],b2[1]],
  [s[2],b1[2],b2[2]]
];
const splitIndex=Math.abs(det(splitMatrix));
assert.equal(splitIndex,3);

// The incidence-selected lattice color matrix C is conjugate to A.
const C=[[1,3],[-1,-2]],X=[[1,1],[0,-1]];
assert.ok(eq(mm(C,X),mm(X,A)));
assert.equal(Math.abs(det(X)),1);

const mod=(M,p)=>M.map(r=>r.map(x=>((x%p)+p)%p));
const N3=mod(A.map((r,i)=>r.map((x,j)=>x-(i===j?1:0))),3);
assert.ok(eq(mod(mm(N3,N3),3),[[0,0],[0,0]]));
assert.notDeepEqual(N3,[[0,0],[0,0]]);

console.log(JSON.stringify({
  protocol:'incidence-selected-lattice-as-c3-augmentation-ideal/1',
  groupRingBasis:['1','g','g^2'],
  augmentationMap:'epsilon(a0+a1*g+a2*g^2)=a0+a1+a2',
  augmentationIdealBasis:{b1,b2},
  colorActionOnAugmentationIdeal:A,
  incidenceSelectedColorAction:C,
  unimodularIntertwiner:X,
  integrallyIsomorphic:true,
  trivialPlusAugmentationSplitIndex:splitIndex,
  integralNonSplitting:'Z*(1+g+g^2) plus ker(epsilon) has index 3 in Z[C3]; a direct projector needs division by 3.',
  characteristicThree:{action:mod(A,3),nilpotentPart:N3,jordanType:'J2(1)'},
  topologicalMeaning:'The active lattice is the canonical zero-sum local coefficient module of a three-sheet color cover.',
  protectionBoundary:'This canonically protects the abstract integral C3 module, but not its particular embedding across the four colored Standard-Model sectors. Furey incidence still supplies that embedding.',
  passed:true
},null,2));
